"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["3736"],{39092(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.auth.impedido_por_inscricao_no_processo","status":403,"titulo":"Impedido de atuar no processo seletivo"},"descricao":{"codigo":"uniplus.auth.impedido_por_inscricao_no_processo","requisitos":["UNI-REQ-0182"],"oQueAconteceu":["Voc\xea tem uma inscri\xe7\xe3o enviada, e n\xe3o cancelada, neste processo seletivo. Quem\\nconcorre em um processo tem interesse direto no resultado e fica impedido de\\natuar na opera\xe7\xe3o dele (Lei n\xba 9.784/1999, art. 18, I). Por isso a opera\xe7\xe3o foi\\nrecusada com **403**, mesmo que voc\xea tenha autoriza\xe7\xe3o para ela.","O impedimento vale para todo o processo, e n\xe3o s\xf3 para o curso em que voc\xea\\nconcorre: configurar, retificar, analisar pedidos, compor banca, avaliar, julgar\\nrecurso, classificar, homologar e consultar dados de outros candidatos. Ele vale\\na partir do envio da inscri\xe7\xe3o, inclusive para autoriza\xe7\xf5es recebidas antes, e\\nn\xe3o h\xe1 libera\xe7\xe3o. O que voc\xea fez antes do envio continua registrado.","Neste processo, voc\xea continua com os mesmos direitos de qualquer candidato:\\nacompanha a pr\xf3pria inscri\xe7\xe3o e consulta o processo publicado. Nos outros\\nprocessos seletivos, em que n\xe3o est\xe1 inscrito, voc\xea atua normalmente."],"comoResolver":["A opera\xe7\xe3o precisa ser feita por outra pessoa da equipe que opera o processo.\\nAvise quem coordena a equipe para redistribuir o trabalho. Pedir nova\\nautoriza\xe7\xe3o n\xe3o resolve, porque o impedimento prevalece sobre qualquer\\nconcess\xe3o.","Se a inscri\xe7\xe3o for cancelada, o impedimento acaba e voc\xea volta a atuar no\\nprocesso."],"ondeAparece":["Qualquer opera\xe7\xe3o com escopo de processo seletivo, quando quem a pede tem inscri\xe7\xe3o enviada e n\xe3o cancelada nesse processo"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Autentica\xe7\xe3o e acesso"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);